#include <torch/extension.h>
#include <cuda_runtime.h>

template<int TILE_SIZE, int UNROLL_FACTOR>
__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Position in output matrix
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tile_idx = t + u;
            if (tile_idx < num_tiles) {
                // Load tile from A
                int a_col = tile_idx * TILE_SIZE + tx;
                if (row < N && a_col < N) {
                    As[ty][tx] = A[row * N + a_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                // Load tile from B
                int b_row = tile_idx * TILE_SIZE + ty;
                if (b_row < N && col < N) {
                    Bs[ty][tx] = B[b_row * N + col];
                } else {
                    Bs[ty][tx] = 0.0f;
                }
